void collect(def node, List path, List out) {
  if (path.size() > 32) { throw new IllegalArgumentException('Telemetry content exceeds the redaction depth limit'); }
  if (node instanceof String) { out.add(['path': path, 'value': node, 'original': node]); }
  else if (node instanceof Map) {
    for (def entry : node.entrySet()) { def next = new ArrayList(path); next.add(entry.getKey()); collect(entry.getValue(), next, out); }
  } else if (node instanceof List) {
    for (int i=0; i<node.size(); i++) { def next = new ArrayList(path); next.add(i); collect(node[i], next, out); }
  }
}
ctx._demo_redaction = [];
for (def field : ['body', 'message']) {
  if (ctx.containsKey(field)) { collect(ctx[field], [field], ctx._demo_redaction); }
}
if (ctx.status instanceof Map && ctx.status.message != null) { collect(ctx.status.message, ['status', 'message'], ctx._demo_redaction); }
if (ctx.attributes instanceof Map) {
  for (def field : params.content_fields) {
    if (ctx.attributes.containsKey(field)) { collect(ctx.attributes[field], ['attributes', field], ctx._demo_redaction); }
  }
}

if (ctx.remove('_demo_redaction_failed') == true) { throw new IllegalArgumentException('Required telemetry redaction failed'); }
int count = 0;
for (def item : ctx._demo_redaction) {
  def parent = ctx;
  for (int i=0; i<item.path.size()-1; i++) { parent = parent[item.path[i]]; }
  parent[item.path[item.path.size()-1]] = item.value;
  if (item.value != item.original) { count++; }
}
ctx.remove('_demo_redaction');
if (!(ctx.attributes instanceof Map)) { ctx.attributes = [:]; }
ctx.attributes['privacy.processor'] = 'elasticsearch-redact';
ctx.attributes['privacy.mode'] = 'elasticsearch_ingest';
ctx.attributes['privacy.pipeline'] = 'agentic-demo-otel-redact';
ctx.attributes['privacy.action'] = count > 0 ? 'obfuscated' : 'no_match';
ctx.attributes['privacy.redacted_fields'] = count;
